def process(parse_html_full):
    rows = parse_html_full[parse_html_full['table_idx'] == 1]['cells'].tolist()
    records = []
    for cells in rows:
        if not isinstance(cells, list) or len(cells) < 3:
            continue
        name = cells[0]
        est2024 = cells[1]
        cen2020 = cells[2]
        # skip header row
        if name == 'Metropolitan statistical area' or '2024' in name or '2020' in name:
            continue
        # clean numeric
        try:
            pop2024 = int(str(est2024).replace(',', '').replace('\u2212', '-').strip())
            pop2020 = int(str(cen2020).replace(',', '').replace('\u2212', '-').strip())
        except:
            continue
        records.append({'msa_name': name, 'pop_2024': pop2024, 'pop_2020': pop2020})
    return pd.DataFrame(records)

